import React, { useState } from 'react';
import axios from 'axios';
import { useNavigate } from 'react-router-dom';
import { ref, push } from 'firebase/database';
import { database } from '../firebase';

const TMDB_API_KEY = 'YOUR_TMDB_API_KEY'; // TMDB API anahtarınızı buraya ekleyin
const TMDB_BASE_URL = 'https://api.themoviedb.org/3';
const TMDB_IMAGE_BASE_URL = 'https://image.tmdb.org/t/p/w500';

function SearchSeries() {
  const [searchQuery, setSearchQuery] = useState('');
  const [searchResults, setSearchResults] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const navigate = useNavigate();

  const handleSearch = async (e) => {
    e.preventDefault();
    if (!searchQuery.trim()) return;

    setLoading(true);
    setError(null);

    try {
      const response = await axios.get(`${TMDB_BASE_URL}/search/tv`, {
        params: {
          api_key: TMDB_API_KEY,
          query: searchQuery,
          language: 'tr-TR',
        },
      });

      setSearchResults(response.data.results);
    } catch (err) {
      setError('Dizi araması sırasında bir hata oluştu. Lütfen tekrar deneyin.');
      console.error('Search error:', err);
    } finally {
      setLoading(false);
    }
  };

  const handleSeriesSelect = async (series) => {
    try {
      setLoading(true);
      setError(null);

      // Seçilen dizinin detaylarını al
      const detailsResponse = await axios.get(`${TMDB_BASE_URL}/tv/${series.id}`, {
        params: {
          api_key: TMDB_API_KEY,
          language: 'tr-TR',
        },
      });

      const seriesDetails = detailsResponse.data;

      // Diziyi Firebase'e ekle
      const newSeries = {
        title: seriesDetails.name,
        coverImage: seriesDetails.poster_path ? `${TMDB_IMAGE_BASE_URL}${seriesDetails.poster_path}` : '',
        totalSeasons: seriesDetails.number_of_seasons,
        currentSeason: 1,
        currentEpisode: 1,
        episodesPerSeason: seriesDetails.episode_run_time?.[0] || 0,
        watchedEpisodes: {
          Beyza: {},
          Mücahit: {},
        },
        createdAt: new Date().toISOString(),
      };

      const seriesRef = ref(database, 'series');
      await push(seriesRef, newSeries);

      navigate('/series');
    } catch (err) {
      setError('Dizi eklenirken bir hata oluştu. Lütfen tekrar deneyin.');
      console.error('Add series error:', err);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-purple-50 to-pink-50 py-12 px-4 sm:px-6 lg:px-8">
      <div className="max-w-7xl mx-auto">
        <div className="text-center mb-12">
          <h1 className="text-4xl font-bold text-gray-900 mb-4">Dizi Ara</h1>
          <p className="text-lg text-gray-600">TMDB veritabanından dizi arayın ve kolayca ekleyin</p>
        </div>

        <form onSubmit={handleSearch} className="max-w-xl mx-auto mb-12">
          <div className="flex gap-4">
            <input
              type="text"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              placeholder="Dizi adı girin..."
              className="flex-1 rounded-lg border-gray-300 shadow-sm focus:border-purple-500 focus:ring-purple-500"
            />
            <button
              type="submit"
              disabled={loading}
              className="bg-purple-600 text-white px-6 py-2 rounded-lg hover:bg-purple-700 transition-colors disabled:opacity-50"
            >
              {loading ? 'Aranıyor...' : 'Ara'}
            </button>
          </div>
        </form>

        {error && (
          <div className="max-w-xl mx-auto mb-8 p-4 bg-red-50 text-red-700 rounded-lg">
            {error}
          </div>
        )}

        {searchResults.length > 0 && (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
            {searchResults.map((series) => (
              <div
                key={series.id}
                className="bg-white rounded-lg shadow-md overflow-hidden hover:shadow-lg transition-shadow"
              >
                {series.poster_path ? (
                  <img
                    src={`${TMDB_IMAGE_BASE_URL}${series.poster_path}`}
                    alt={series.name}
                    className="w-full h-96 object-cover"
                  />
                ) : (
                  <div className="w-full h-96 bg-gray-200 flex items-center justify-center">
                    <span className="text-gray-400">Görsel yok</span>
                  </div>
                )}
                <div className="p-4">
                  <h3 className="text-lg font-semibold text-gray-900 mb-2">{series.name}</h3>
                  <p className="text-sm text-gray-600 mb-4">
                    {series.first_air_date ? new Date(series.first_air_date).getFullYear() : 'Yıl bilgisi yok'}
                  </p>
                  <button
                    onClick={() => handleSeriesSelect(series)}
                    disabled={loading}
                    className="w-full bg-purple-600 text-white px-4 py-2 rounded-md hover:bg-purple-700 transition-colors disabled:opacity-50"
                  >
                    {loading ? 'Ekleniyor...' : 'Diziyi Ekle'}
                  </button>
                </div>
              </div>
            ))}
          </div>
        )}

        {searchQuery && !loading && searchResults.length === 0 && (
          <div className="text-center text-gray-600">
            Sonuç bulunamadı. Lütfen farklı bir arama terimi deneyin.
          </div>
        )}
      </div>
    </div>
  );
}

export default SearchSeries;
